package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_previousSibling_TriageGen1Test {

    @Test
    public void testPreviousSibling_NoSiblings_ReturnsNull() {
        Node node = new Node("", new Attributes());
        assertNull(node.previousSibling());
    }

    @Test
    public void testPreviousSibling_OneSibling_ReturnsSibling() {
        Node parent = new Node("", new Attributes());
        Node sibling = new Node("", new Attributes());
        parent.childNodes.add(sibling);
        sibling.setSiblingIndex(0);
        assertEquals(sibling, parent.previousSibling());
    }

    @Test
    public void testPreviousSibling_MultipleSiblings_ReturnsSecondToLastSibling() {
        Node parent = new Node("", new Attributes());
        Node sibling1 = new Node("", new Attributes());
        Node sibling2 = new Node("", new Attributes());
        Node sibling3 = new Node("", new Attributes());
        parent.childNodes.add(sibling1);
        parent.childNodes.add(sibling2);
        parent.childNodes.add(sibling3);
        sibling1.setSiblingIndex(0);
        sibling2.setSiblingIndex(1);
        sibling3.setSiblingIndex(2);
        assertEquals(sibling2, parent.previousSibling());
    }

    @Test
    public void testPreviousSibling_GettingPreviousSiblingOfFirstSibling_ReturnsNull() {
        Node parent = new Node("", new Attributes());
        Node sibling1 = new Node("", new Attributes());
        Node sibling2 = new Node("", new Attributes());
        parent.childNodes.add(sibling1);
        parent.childNodes.add(sibling2);
        sibling1.setSiblingIndex(0);
        sibling2.setSiblingIndex(1);
        assertNull(sibling1.previousSibling());
    }

    @Test
    public void testPreviousSibling_NullParentNode_ThrowsNPE() {
        Node node = new Node("", new Attributes());
        node.parentNode = null;
        try {
            node.previousSibling();
            fail("Expected NPE");
        } catch (NullPointerException e) {
            // Expected
        }
    }

    @Test
    public void testPreviousSibling_NullSiblingsArray_ThrowsNPE() {
        Node node = new Node("", new Attributes());
        node.parentNode = new Node("", new Attributes());
        node.parentNode.childNodes = null;
        try {
            node.previousSibling();
            fail("Expected NPE");
        } catch (NullPointerException e) {
            // Expected
        }
    }
}
